// Package proxystatus pkg/proxystatus/font.go c4-app-web
package proxystatus

// mononokiWoff2 is the base64-encoded WOFF2 data for the mononoki monospace font,
// copied verbatim from cmd/skywire-cli/commands/rewards/server/fonts.go
// (MononokiWoff2). pkg/proxystatus cannot import that CLI package, so the constant
// is duplicated here rather than shared. It is embedded once in the page shell as an
// @font-face data-URI (never in the streamed RenderFragment) so the route tree's
// box-drawing glyphs and the full public keys render in a true fixed-width font and
// line up column-for-column.

// fontFace is the @font-face CSS rule that registers the embedded mononoki as the
// "Mononoki" family via a woff2 data-URI. Render writes it into the page-shell
// <style> exactly once per load (font-display:swap so text paints immediately even
// before the font decodes). It is deliberately NOT part of css / RenderFragment: the
// live region streams over the WebSocket every ~1s and must not re-carry ~38 KB of
// font on every push.
const fontFace = `@font-face{font-family:'Mononoki';font-style:normal;font-weight:400;font-display:swap;` +
	`src:url(data:font/woff2;base64,` + mononokiWoff2 + `) format('woff2')}`
const mononokiWoff2 = ""
